def sort_build_ids(ids: list[str]) -> list[str]:
    def key(s: str):
        base, sep, tag = s.partition('~')
        prefix, num = base.split('-', 1)
        major, minor = map(int, num.split('.'))
        return (prefix, major, minor, 0 if sep else 1, tag)
    return sorted(ids, key=key)

def prune_stale(entries: list[tuple[str, float]], now: float, ttl: float, max_keep: int) -> int:
    cutoff = now - ttl
    kept = [item for item in entries if item[1] > cutoff]
    entries[:] = kept[-max_keep:] if max_keep > 0 else []
    return len(entries)

def normalize_tree(node):
    if isinstance(node, dict):
        return {k: normalize_tree(v) for k, v in node.items()}
    if isinstance(node, list):
        return [normalize_tree(v) for v in node]
    return node.strip() if isinstance(node, str) else node

def min_subarray_len(nums: list[int], target: int) -> int:
    left = cur = 0
    best = len(nums) + 1
    for right, val in enumerate(nums):
        cur += val
        while cur >= target:
            best = min(best, right - left + 1)
            cur -= nums[left]
            left += 1
    return 0 if best > len(nums) else best

def decode_counts(s: str) -> list[tuple[str, int]]:
    out, i, n = [], 0, len(s)
    while i < n:
        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1
        if i < n:
            out.append((s[i], num))
            i += 1
    return out

from collections import deque
def shortest_hops(adj: dict[int, list[int]], start: int, goal: int) -> int:
    if start == goal:
        return 0
    q = deque([(start, 0)])
    seen = {start}
    while q:
        u, dist = q.popleft()
        for v in adj.get(u, ()):
            if v == goal:
                return dist + 1
            if v not in seen:
                seen.add(v)
                q.append((v, dist + 1))
    return -1
